    "data": {
      "open_questions": [
      ],
      "key_decisions": [
        {
          "title": "Scene = Page (Unity Scene model)",
          "rationale": "Each scene is one full stage, 1:1 with a web page. Assets are placed into scenes. System targets landing pages / static websites, not interactive applications.",
          "date": "2026-04-29"
        },
        {
          "title": "Dual-surface authoring (visual editor + agent API)",
          "rationale": "Human authors via visual canvas editor with drag-and-drop and property panels. AI agent edits programmatically via API on the same scene data. Generalizes the pattern already proven in the melee-3 font app.",
          "date": "2026-04-29"
        },
        {
          "title": "Collapsible group layer model (tree hierarchy)",
          "rationale": "Scene layers form a tree, not a flat stack. Complex assets like the CodeCaine logo are groups that expand to reveal sub-layers with configurable properties. Sub-layers can reference other assets (e.g. video). Other scene assets can interleave between a group's sub-layers. Like Photoshop layer groups or Unity Hierarchy.",
          "date": "2026-04-29"
        },
        {
          "title": "Full replacement of apps/frontend/",
          "rationale": "Scene system replaces the existing frontend entirely. All pages rebuilt as scenes. Everything unified into one application.",
          "date": "2026-04-29"
        },
        {
          "title": "Option A — content separate, assets reusable",
          "rationale": "Assets live in registry as reusable building blocks. Content lives with components. Scenes are lean composition manifests referencing assets by ID. Avoids duplication, keeps editor focused on visual composition.",
          "date": "2026-04-29"
        },
        {
          "title": "Scene data format confirmed (scene.json)",
          "rationale": "JSON with id, name, stage dimensions, and layers array. Layer types: media, effect, glyph-group, component. Groups use children array for sub-layers with interleaving support. Z-order is array position (last on top). Both editor and agent operate on this format.",
          "date": "2026-04-29"
        },
        {
          "title": "Font pipeline stays separate, editor app absorbed",
          "rationale": "Python pipeline is an asset factory — stays in apps/font-creation/. The melee-3 Vite editor app's layer editing capabilities get folded into the scene editor as the glyph-group property inspector. One editor, not two.",
          "date": "2026-04-29"
        },
        {
          "title": "Five asset types on day one",
          "rationale": "All five needed for the title scene vertical slice: glyph-group, media, effect, component, audio.",
          "date": "2026-04-29"
        }
      ]
    }
