erarchy-row'); if (!row || !dragSourcePath) return; e.preventDefault(); const fromPath = e.dataTransfer.getData('application/x-layer-path') || e.dataTransfer.getData('text/plain'); const targetPath = row.dataset.path; if (!fromPath || isAncestorPath(fromPath, targetPath)) return; const pos = computeDropPosition(row, e); const toPath = computeMovePath(getState().scene, targetPath, pos); if (!toPath) return; moveLayer(fromPath, toPath); document.querySelectorAll('.drop-indicator-before, .drop-indicator-after, .drop-indicator-into').forEach(el => el.classList.remove('drop-indicator-before','drop-indicator-after','drop-indicator-into')); dragSourcePath = null. (7) ADD computeMovePath(scene, targetPath, pos) at module scope: parses the target path; for 'before'/'after' returns a sibling path with the index shifted by 0/1; for 'into' returns targetPath + '.children.' + (target.children?.length ?? 0). Implementation: const parts = targetPath.split('.children.'); const lastIdx = Number(parts[parts.length - 1]); const parentPathStr = parts.slice(0, -1).join('.children.'); — if pos === 'into' then targetPath + '.children.' + (resolveLayer(scene, targetPath).children?.length ?? 0); — else const newIdx = pos === 'before' ? lastIdx : lastIdx + 1; return (parentPathStr ? parentPathStr + '.children.' + newIdx : String(newIdx)). (8) UPDATE imports at top of hierarchy.js: add `import { setSelectedPath, subscribe, getState, moveLayer } from '../state.js'` (extending CP4 task 5's imports) and `import { resolveLayer } from '../path.js'`. (9) UPDATE initHierarchyPanel: APPEND panel.addEventListener('dragstart', onDragStart); panel.addEventListener('dragover', onDragOver); panel.addEventListener('drop', onDrop); panel.addEventListener('dragend', onDragEnd). (10) APPEND CSS to editor.css: .hierarchy-row[draggable='true'] { cursor: grab } ; .hierarchy-row.drop-indicator-before { box-shadow: inset 0 2px 0 #4d8 } ; .hierarchy-row.drop-indicator-after { box-shadow: inset 0 -2px 0 #4d8 } ; .hierarchy-row.drop-indicator-into { background: #1d3247; outline: 1px dashed #4d8; outline-offset: -1px }. After this task: dragging the 'crt' top-level row above 'bg-video' reorders it to the bottom of the z-stack (the scanlines disappear since they now render UNDER the bg video — easy visual confirmation). Dragging a peer onto codecaine-logo's middle band drops it as a new last child of the group's children array (visible in the hierarchy as a new row under codecaine-logo). Dragging a child out of codecaine-logo onto the gap above 'crt' moves it to the top level. Self-drop and drop-onto-descendant are silently rejected.",
