/* Title screen */
#title-screen { display: grid; place-items: center; text-align: center; }
#title-screen.active { display: grid; }

.title-logo {
  font-family: 'FolkPro', 'Orbitron', sans-serif;
  font-weight: 900;
  font-size: 280px;
  letter-spacing: 0.04em;
  line-height: 0.9;
  color: transparent;
  background: linear-gradient(180deg, #fff9e0 0%, #f6c419 40%, #8a5a00 75%, #f4e3a3 100%);
  -webkit-background-clip: text; background-clip: text;
  filter: drop-shadow(0 0 30px rgba(246, 196, 25, 0.45)) drop-shadow(0 6px 0 #3a2200);
  text-shadow: 0 0 80px rgba(255, 220, 120, 0.3);
