                { "id": 9, "command": "ADD FUNCTION cloneAlongPath(scene, segs): if (segs.length === 0) return { scene: { ...scene, layers: [...scene.layers] }, parent: null, indexInParent: -1, layer: null }; const sceneClone = { ...scene, layers: [...scene.layers] }; let parentArr = sceneClone.layers; let layer = parentArr[Number(segs[0])]; if (!layer) return null; layer = { ...layer }; parentArr[Number(segs[0])] = layer; for (let i = 1; i < segs.length; i++) { if (!Array.isArray(layer.children)) return null; layer.children = [...layer.children]; const idx = Number(segs[i]); const next = layer.children[idx]; if (!next) return null; const nextClone = { ...next }; layer.children[idx] = nextClone; parentArr = layer.children; layer = nextClone; } const indexInParent = Number(segs[segs.length - 1]); return { scene: sceneClone, parent: parentArr, indexInParent, layer }", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
                { "id": 10, "command": "ADD FUNCTION mutateLayerAt(path, patch): if (!store.scene) return; const segs = splitPath(path); if (segs.length === 0) return; const result = cloneAlongPath(store.scene, segs); if (!result) return; const merged = mergePatch(result.layer, patch); result.parent[result.indexInParent] = merged; store.scene = result.scene; markDirty(); bus.dispatchEvent(new CustomEvent('scene-changed', { detail: result.scene }))", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
                { "id": 11, "command": "ADD FUNCTION addLayerAt(parentPath, index, layer): if (!store.scene) return; const sceneClone = { ...store.scene, layers: [...store.scene.layers] }; let parentArr; if (!parentPath) { parentArr = sceneClone.layers; } else { const segs = splitPath(parentPath); const result = cloneAlongPath(sceneClone, segs); if (!result) return; result.parent[result.indexInParent].children = Array.isArray(result.layer.children) ? [...result.layer.children] : []; parentArr = result.parent[result.indexInParent].children; } const i = Math.max(0, Math.min(parentArr.length, index)); parentArr.splice(i, 0, layer); store.scene = sceneClone; markDirty(); bus.dispatchEvent(new CustomEvent('scene-changed', { detail: sceneClone }))", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
                { "id": 12, "command": "ADD FUNCTION removeLayerAt(path): if (!store.scene) return; const segs = splitPath(path); if (segs.length === 0) return; const result = cloneAlongPath(store.scene, segs); if (!result) return; result.parent.splice(result.indexInParent, 1); store.scene = result.scene; if (store.selectedPath && (store.selectedPath === path || store.selectedPath.startsWith(path + '.children.'))) { store.selectedPath = null; bus.dispatchEvent(new CustomEvent('selection-changed', { detail: null })); } markDirty(); bus.dispatchEvent(new CustomEvent('scene-changed', { detail: result.scene }))", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
                { "id": 13, "command": "ADD FUNCTION moveLayer(fromPath, toPath): if (!store.scene || !fromPath || !toPath || fromPath === toPath) return; const fromSegs = splitPath(fromPath); const toSegs = splitPath(toPath); if (fromSegs.length === 0 || toSegs.length === 0) return; const fromParentSegs = fromSegs.slice(0, -1); const toParentSegs = toSegs.slice(0, -1); const fromIdx = Number(fromSegs[fromSegs.length - 1]); let toIdx = Number(toSegs[toSegs.length - 1]); const sameParent = fromParentSegs.length === toParentSegs.length && fromParentSegs.every((s, i) => s === toParentSegs[i]); if (sameParent && toIdx > fromIdx) toIdx -= 1; const removeRes = cloneAlongPath(store.scene, fromSegs); if (!removeRes) return; const moved = removeRes.layer; removeRes.parent.splice(removeRes.indexInParent, 1); let parentArr; if (toParentSegs.length === 0) { parentArr = removeRes.scene.layers; } else { const insertRes = cloneAlongPath(removeRes.scene, toParentSegs); if (!insertRes) return; insertRes.parent[insertRes.indexInParent].children = Array.isArray(insertRes.layer.children) ? [...insertRes.layer.children] : []; parentArr = insertRes.parent[insertRes.indexInParent].children; } parentArr.splice(Math.max(0, Math.min(parentArr.length, toIdx)), 0, moved); store.scene = removeRes.scene; markDirty(); bus.dispatchEvent(new CustomEvent('scene-changed', { detail: removeRes.scene }))", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
