                { "id": 9, "command": "ADD FUNCTION cloneAlongPath(scene, segs): if (segs.length === 0) return { scene: { ...scene, layers: [...scene.layers] }, parent: null, indexInParent: -1, layer: null }; const sceneClone = { ...scene, layers: [...scene.layers] }; let parentArr = sceneClone.layers; let layer = parentArr[Number(segs[0])]; if (!layer) return null; layer = { ...layer }; parentArr[Number(segs[0])] = layer; for (let i = 1; i < segs.length; i++) { if (!Array.isArray(layer.children)) return null; layer.children = [...layer.children]; const idx = Number(segs[i]); const next = layer.children[idx]; if (!next) return null; const nextClone = { ...next }; layer.children[idx] = nextClone; parentArr = layer.children; layer = nextClone; } const indexInParent = Number(segs[segs.length - 1]); return { scene: sceneClone, parent: parentArr, indexInParent, layer }", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
                { "id": 10, "command": "ADD FUNCTION mutateLayerAt(path, patch): if (!store.scene) return; const segs = splitPath(path); if (segs.length === 0) return; const result = cloneAlongPath(store.scene, segs); if (!result) return; const merged = mergePatch(result.layer, patch); result.parent[result.indexInParent] = merged; store.scene = result.scene; markDirty(); bus.dispatchEvent(new CustomEvent('scene-changed', { detail: result.scene }))", "file": "apps/scene-engine/editor/src/state.js", "status": "pending" },
