: 'cover', blend: 'normal', opacity: 1.0 } }; case 'effect': return { ...base, properties: { opacity: 1.0 } }; case 'glyph-group': return { ...base, position: { x: Math.round(x), y: Math.round(y) }, properties: { scale: 0.18 } }; case 'component': return { ...base, position: { x: Math.round(x), y: Math.round(y) }, properties: {} }; case 'audio': return { ...base, properties: { volume: 1.0, loop: true } }; default: return { ...base, properties: {} }; }. Position is omitted for media/effect because those layer types fill the stage by default in the renderer. For glyph-group and component the drop coords become the initial position in stage-pixel space (numeric; the spec also supports 'center'/'%', but the dropped layer starts numeric so the user can tweak via inspector or further drag). (4) ADD FUNCTION uniqueLayerId(assetId, scene): given an asset id like 'codecaine-logo', produce 'codecaine-logo' if no existing layer.id collides, else suffix '-2', '-3', etc. Walk scene.layers + recursive children to gather every existing layer.id. (5) ADD FUNCTION initCanvasDrop(): const stage = document.getElementById('panel-canvas-stage'); if (!stage) return; stage.addEventListener('dragover', onDragOver); stage.addEventListener('dragleave', onDragLeave); stage.addEventListener('drop', onDrop). EXPORT initCanvasDrop as named export. (6) UPDATE editor/src/main.js: APPEND import { initCanvasDrop } from './panels/canvas-drop.js' and call initCanvasDrop() inside boot() AFTER initCanvasHighlight() and BEFORE loadEditorScene(). (7) APPEND CSS to editor.css: .asset-row[draggable='true'] { cursor: grab } ; .asset-row[draggable='true']:active { cursor: grabbing } ; #panel-canvas-stage.is-drop-target { outline: 2px dashed #4d8; outline-offset: -2px }. After this task: dragging 'in-text-fire' from the asset browser onto an empty area of the canvas adds a new top-level media layer and the video starts playing fullscreen on top of the existing layers; dragging 'codecaine-logo' onto the canvas 