              "description": "Wire the first authoring drag flow: drag an asset-browser row, drop on the canvas, get a new layer added to the scene. (1) Update apps/scene-engine/editor/src/panels/asset-browser.js: in renderGroup's li construction, ADD li.draggable = true and an inline 'dragstart' listener that calls e.dataTransfer.setData('application/x-asset-id', id) AND e.dataTransfer.setData('text/plain', id) (text/plain fallback for browsers that strip custom MIME types in some contexts) AND e.dataTransfer.effectAllowed = 'copy'. The id comes from the closure variable already present in the loop. (2) CREATE FILE apps/scene-engine/editor/src/panels/canvas-drop.js exporting initCanvasDrop(). Imports: getState from ../state.js, addLayerAt from ../state.js. Behavior: a) onDragOver(e) → if e.dataTransfer.types.includes('application/x-asset-id'), e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; #panel-canvas-stage.classList.add('is-drop-target'); b) onDragLeave(e) → if e.target === stage, remove .is-drop-target; c) onDrop(e) → e.preventDefault(); remove .is-drop-target; const assetId = e.dataTransfer.getData('application/x-asset-id') || e.dataTransfer.getData('text/plain'); if (!assetId) return; const { registry, scene } = getState(); const entry = registry?.[assetId]; if (!entry || !scene) { console.warn('[canvas-drop] unknown asset', assetId); return; } compute drop coordinates relative to the stage's INTRINSIC 1440×1080 coords: const rect = stage.getBoundingClientRect(); const scale = rect.width / 1440 || 1; const x = (e.clientX - rect.left) / scale; const y = (e.clientY - rect.top) / scale; build newLayer = layerForAsset(assetId, entry, { x, y }); call addLayerAt('', scene.layers.length, newLayer). (3) ADD FUNCTION layerForAsset(assetId, entry, { x, y }) at module scope: const newId = uniqueLayerId(assetId, getState().scene); const base = { id: newId, type: entry.type, asset: assetId }; switch (entry.type) { case 'media': return { ...base, properties: { fit